106	/**
107	 * Packs a colony into the cells texture, two bytes per arena cell: its
108	 * density - 0 for an empty cell, from 0.55 up for a bacterium, by its
109	 * strength - and its overcharge. This is all the CPU does for a colony; the
110	 * blur, the outline, the gloss and the shimmer run on the GPU.
111	 *
112	 * Only the cells in `box` are packed, the rest of `out` is left as it was:
113	 * what is uploaded and read this frame is no more than that box.
114	 */
115	export function encodeCells(
116	  out: Uint8Array,
117	  width: number,
118	  bacterias: CellList,
119	  balance: GameBalance,
120	  box: CellBox
121	): void {
122	  const [x0, y0, x1, y1] = box;
123	  for (let y = y0; y < y1; y++) {
124	    out.fill(0, (y * width + x0) * 2, (y * width + x1) * 2);
125	  }
126	  const { x: xs, y: ys, energy: energies, length } = bacterias;
127	  for (let i = 0; i < length; i++) {
128	    const x = xs[i];
129	    const y = ys[i];
130	    const energy = energies[i];
131	    if (x < x0 || x >= x1 || y < y0 || y >= y1) {
132	      continue;
133	    }
134	    const index = (y * width + x) * 2;
135	    out[index] = Math.round(255 * cellDensity(strengthOf(energy, balance)));
136	    out[index + 1] = Math.round(255 * overcharge(energy, balance));
137	  }
138	}
