291	  /** A painter for the canvas, or null where WebGL2 is not available. */
292	  public static create(
293	    canvas: HTMLCanvasElement,
294	    width: number,
295	    height: number,
296	    detail: number,
297	    unit: number
298	  ): GlArenaPainter | null {
299	    let gl: WebGL2RenderingContext | null = null;
300	    try {
301	      gl = canvas.getContext('webgl2', {
302	        alpha: false,
303	        antialias: false,
304	        depth: false,
305	        stencil: false,
306	        premultipliedAlpha: false,
307	        // Keeping the drawing buffer costs a copy of the canvas every frame
308	        // on many GPUs - a snapshot asks for `showLastFrame` instead.
309	        preserveDrawingBuffer: false,
310	      });
311	    } catch {
312	      return null;
313	    }
314	    return gl == null
315	      ? null
316	      : new GlArenaPainter(canvas, gl, width, height, detail, unit);
317	  }
318	
319	  private constructor(
320	    canvas: HTMLCanvasElement,
321	    private readonly gl: WebGL2RenderingContext,
322	    private readonly width: number,
323	    private readonly height: number,
324	    detail: number,
325	    unit: number
326	  ) {
327	    // Sized by `createArenaPainter`.
328	    this.canvasWidth = canvas.width;
329	    this.canvasHeight = canvas.height;
330	    this.renderWidth = canvas.width;
331	    this.renderHeight = canvas.height;
332	    this.unit = unit;
333	    this.detail = detail;
334	    this.view = { x: 0, y: 0, width, height };
335	    this.motes = new Motes(width, height);
336	    this.weapons = new WeaponFx(unit);
337	    this.cellBytes = new Uint8Array(width * height * 2);
338	    this.resources = this.setup();
339	
340	    canvas.addEventListener('webglcontextlost', (event) => {
341	      if (this.disposed) {
342	        return;
343	      }
344	      // Without this the browser would never hand the context back.
345	      event.preventDefault();
346	      this.resources = null;
347	    });
348	    canvas.addEventListener('webglcontextrestored', () => {
349	      if (this.disposed) {
350	        return;
351	      }
352	      this.resources = this.setup();
353	      // The old context's queries and layers went with it.
354	      this.timer = undefined;
355	      this.wallsFor = null;
356	      if (this.theme != null) {
357	        this.uploadFloor(this.theme);
358	      }
359	      this.uploadZones(this.zones);
360	    });
361	  }
