391	  /**
392	   * Hands the context back to the browser right away rather than once the
393	   * canvas is collected - a page may only hold a few WebGL contexts.
394	   */
395	  public dispose(): void {
396	    this.disposed = true;
397	    this.resources = null;
398	    this.timer?.dispose();
399	    this.gl.getExtension('WEBGL_lose_context')?.loseContext();
