402	  public setRenderScale(scale: number): void {
403	    const width = Math.max(1, Math.round(this.canvasWidth * scale));
404	    const height = Math.max(1, Math.round(this.canvasHeight * scale));
405	    if (width === this.renderWidth && height === this.renderHeight) {
406	      return;
407	    }
408	    const from = { width: this.renderWidth, height: this.renderHeight };
409	    this.renderWidth = width;
410	    this.renderHeight = height;
411	    const resources = this.resources;
412	    // Without a context, the restored one builds it at that size.
413	    if (resources == null) {
414	      return;
415	    }
416	    // The last frame goes along, scaled: the trail goes on from it, and a
417	    // snapshot before the next frame shows it rather than black.
418	    const gl = this.gl;
419	    const old = resources.trail;
420	    const trail = this.target(width, height, gl.LINEAR);
421	    gl.disable(gl.SCISSOR_TEST);
422	    gl.bindFramebuffer(gl.READ_FRAMEBUFFER, old.framebuffer);
423	    gl.bindFramebuffer(gl.DRAW_FRAMEBUFFER, trail.framebuffer);
424	    gl.blitFramebuffer(
425	      0,
426	      0,
427	      from.width,
428	      from.height,
429	      0,
430	      0,
431	      width,
432	      height,
433	      gl.COLOR_BUFFER_BIT,
434	      gl.LINEAR
435	    );
436	    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
437	    gl.deleteFramebuffer(old.framebuffer);
438	    gl.deleteTexture(old.texture);
439	    resources.trail = trail;
440	  }
